      '【答え】北関東工業地域\n\n【どこにあるか】群馬県・栃木県・茨城県の内陸部と、埼玉県北部にかけて広がる。\n\n【なぜ内陸なのに発展したのか】ふつう工業は港のある海ぞいで発展する。ここでは高速道路がその役割を果たした。関越自動車道・東北自動車道・北関東自動車道が整い、トラックで原料も製品も運べるようになった。海ぞいとくらべて土地が安く広く、働く人も確保しやすい。道路が港のかわりになったというのが要点である。\n\n【何をつくっているか】自動車・電気機械・電子部品・食品など、重い原料を必要としない組み立て型の工業が中心である。原料が軽ければ、港から遠くても不利にならない。\n\n【工業団地】地方公共団体が土地を整えて工場を誘致した工業団地が各地につくられた。地元に働く場所ができ、若い人が都市へ出ていくのを防ぐねらいもあった。\n\n【外国とのつながり】群馬県大泉町のように、工場で働く日系ブラジル人などの外国人が多く住む町もあり、多文化共生の課題を考える例になる。\n\n【よくあるまちがい】「地帯」ではなく「地域」と呼ぶ。戦前から発達した4つ（京浜・中京・阪神・北九州）を地帯、戦後に発達したものを地域と呼び分ける。',
