      '【答え】太平洋ベルト\n\n【どこを通るか】関東地方から九州地方北部にかけて、太平洋や瀬戸内海のぞいに帯のように連なる。京浜 → 京葉 → 東海 → 中京 → 阪神 → 瀬戸内 → 北九州の順にたどれる。\n\n【なぜここに集まるのか】\n①港がある … 日本は原料のほとんどを輸入し、製品を輸出する加工貿易の国である。大型船が着ける港のそばに工場を置けば、原料を運ぶ費用が最も安くすむ\n②大消費地に近い … 東京・名古屋・大阪などの大都市が並び、製品がすぐ売れ、働く人も集まる\n③平地がある … 太平洋側には広い平野があり、埋め立て地も造成しやすかった\n\n【どれくらい集中しているか】国土の面積では一部にすぎないが、工業出荷額の大部分と人口のおよそ半分がこの帯に集まっている。\n\n【問題点】大気汚染や水質汚濁などの公害、地価の高騰、交通渋滞。いっぽうで日本海側や内陸では過疎が進んだ。集中と過疎は表と裏の関係にある。\n\n【近年の変化】内陸に高速道路が整い、北関東工業地域のように港から離れた場所でも工業が育つようになった。軽くて高価な製品なら、港の近さは決め手にならないためである。',
