    explanation:
      '【答え】抑制栽培（高冷地農業）\n\n【なぜ高原なのか】レタスやキャベツは暑さに弱く、気温が高いとうまく育たない。夏には平地の産地が出荷できなくなる。ところが標高が高い土地は気温が低い。およそ100m上がるごとに0.6℃下がるので、標高1000mの高原は同じ地域の平地より6℃ほどすずしい。だから夏でも作れる。\n\n【なぜもうかるのか】ほかの産地が出せない時期に出荷できるので、高い値段で売れる。出荷の時期をずらすことで、気候の不利を有利に変えている。\n\n【どこで行われているか】長野県の野辺山原（八ヶ岳のふもと）、群馬県の嬬恋村（浅間山のふもと）。どちらも火山のふもとの高原である。\n\n【運ぶくふう】高原は大消費地から遠いので、保冷トラックで新鮮なうちに運ぶ。高速道路の整備が産地の発展を支えた。\n\n【対にして覚える】\n・促成栽培 … あたたかい宮崎・高知で、出荷を早める\n・抑制栽培 … すずしい長野・群馬で、出荷を遅らせる\nどちらも「ほかが出せない時期に出す」という同じねらいである。漢字の意味で分けると取りちがえない。促は早める、抑はおさえる。',
