      '【答え】栽培漁業\n\n【どういう漁業か】卵からかえした稚魚や稚貝を、自分の力で生きられる大きさまで人の手で育て、川や海に放流する。その後は自然の中で育ち、大きくなってからとる。\n\n【なぜこの方法をとるのか】自然のままでは、卵や稚魚のうちにほとんどが他の魚に食べられてしまう。いちばん弱い時期だけ人が守ってやれば、生き残る数がぐんと増える。弱い時期だけ助けて、あとは自然にまかせるという考え方である。これにより、資源を減らさずに漁を続けられる。\n\n【養殖業とのちがい】ここが必ず問われる。\n・養殖業 … 出荷できる大きさになるまで、ずっと人が育てる\n・栽培漁業 … 途中で放流し、自然の中で育ててからとる\n「最後まで育てるか、途中で放すか」で分ける。\n\n【対象になる生き物】さけ・ひらめ・まだい・くるまえび・あわびなど。さけは生まれた川に戻る性質があるので、稚魚を放流して数年後に帰ってきたものをとる。\n\n【持続可能な漁業】このほか、とってよい量を決める漁獲量の制限、小さい魚を逃がす網目の大きな網、産卵期の禁漁など。海の資源は無限ではないという前提で管理する考え方が広がっている。',
