    explanation:
      '【答え】赤道\n\n【どんな線か】緯度0度の線で、地球を北半球と南半球に分ける。地球を一周する線の中で最も長く、およそ4万kmある。\n\n【どこを通るか】アフリカ大陸の中部、インドネシアの島々、南アメリカ大陸の北部（アマゾン川流域）を通る。地図でこの3か所を覚えておくと、位置をまちがえない。\n\n【なぜ赤道付近は暑いのか】地球は丸いので、赤道付近では太陽の光がほぼ真上から当たる。同じ量の光が狭い面積に集まるため、地面がよくあたたまる。高緯度では光が斜めに当たり、同じ量の光が広い面積に散らばるので、あたたまりにくい。当たり方の角度で気温が決まる。\n\n【赤道付近の気候】強い日射であたためられた空気が上昇し、雲ができて雨が多い。だから熱帯雨林が広がる。\n\n【緯度のはたらき】\n・気候帯が緯度で並ぶ … 熱帯 → 乾燥帯 → 温帯 → 冷帯 → 寒帯\n・南半球では季節が逆になる\n・北緯66.6度より高い所では白夜や極夜が起きる\n\n【あわせて覚える】経度0度は本初子午線で、イギリスのロンドンを通る。緯度と経度をセットで覚える。',
