      '【答え】本初子午線\n\n【どんな線か】経度0度の線で、イギリスのロンドン郊外にある旧グリニッジ天文台を通る。ここを基準に、東へ180度を東経、西へ180度を西経と数える。\n\n【なぜイギリスなのか】自然に決まったものではなく、1884年の国際会議で決められた。当時のイギリスが海運と地図づくりで最も進んでいたことが理由である。緯度は赤道という自然の基準があるが、経度の基準は人が決めたものという点が両者の大きなちがいである。\n\n【時差の計算】地球は24時間で1回転（360度）するので、360÷24＝15、つまり経度15度で1時間の時差が生じる。\n・日本の標準時は東経135度（兵庫県明石市を通る）。135÷15＝9なので、ロンドンより9時間進んでいる\n・東にあるほど時刻が早い。日本のほうがロンドンより先に朝を迎える\n\n【日付変更線】およそ経度180度に引かれた線。西から東へこえるときは日付を1日もどし、東から西へこえるときは1日進める。国の中で日付が分かれないよう、線は折れ曲がっている。\n\n【覚え方】赤道は自然が決めた緯度0度、本初子午線は人が決めた経度0度。',
