      '【答え】鉄砲\n\n【いつ・どこへ】1543年、種子島（鹿児島県）に流れ着いた中国船に乗っていたポルトガル人によって伝えられた。日本人が初めてヨーロッパ人と出会った出来事でもある。\n\n【なぜ広まったのか】当時は戦国時代で、各地の大名が新しい武器を強く求めていた。堺（大阪府）や国友（滋賀県）などで大量に生産されるようになり、わずか数十年で日本は世界有数の鉄砲保有国になった。必要とする人がいたから、技術は急速に広まった。\n\n【何が変わったのか】\n・戦い方 … 一騎打ちから、足軽が鉄砲を持って集団で戦う形へ。1575年の長篠の戦いで、織田信長・徳川家康の連合軍が鉄砲を大量に使い、武田の騎馬隊を破ったことがよく知られる\n・城のつくり … 弓矢を防ぐ造りでは足りなくなり、堀を広く深く、石垣を高くした平山城・平城へ変わった\n・天下統一が早まった … 大量の鉄砲を買える経済力のある大名が有利になった\n\n【あわせて覚える】1549年にはフランシスコ・ザビエルがキリスト教を伝えた。鉄砲とキリスト教はセットで問われる（南蛮貿易）。',
