      '【答え】満州事変\n\n【何が起きたか】1931年9月18日、奉天郊外の柳条湖で、日本の関東軍が南満州鉄道の線路を自ら爆破し、これを中国側のしわざだとして軍事行動を始めた。半年ほどで満州の主要部を占領し、1932年に満州国の建国を宣言した。\n\n【なぜ重大なのか】この行動は、日本政府の方針にも天皇の命令にもよらない、現地の軍による独断だった。それでも政府は後から追認するしかなかった。政治が軍を抑えられなくなったことが、ここではっきりしたのである。\n\n【なぜ満州を求めたのか】世界恐慌で日本経済は行きづまっていた。資源と土地を求め、満州を「日本の生命線」とする主張が広まり、多くの農民が開拓団として送りこまれた。\n\n【満州国】清の最後の皇帝であった溥儀を元首にすえたが、政治も軍も関東軍が握っていた。直接の植民地にすると国際的な批判が強くなるため、独立国という体裁をとった。\n\n【国際社会の反応】国際連盟はリットン調査団を送り、日本の行動を侵略と認めて満州国を承認しなかった。これに反発した日本は1933年に国際連盟を脱退し、孤立していく。\n\n【流れ】満州事変（1931）→ 五・一五事件（1932）→ 国際連盟脱退（1933）→ 二・二六事件（1936）→ 日中戦争（1937）。',
    examFrequency: 'high',
