      '【答え】国際連合（国連）\n\n【いつ・どうやって】第二次世界大戦が終わった1945年10月24日、51か国で発足した。現在の加盟国は193か国で、日本は1956年に加盟した。本部はアメリカのニューヨークにある。\n\n【なぜつくられたのか】第一次世界大戦の後にできた国際連盟は、戦争を防げなかった。その反省から3点が改められた。\n①提案国のアメリカが国際連盟に加盟しなかった → 国連には大国がそろって参加している\n②全会一致が原則で何も決められなかった → 多数決を採用した\n③軍事的な力を持たなかった → 安全保障理事会の決議にもとづいて平和維持活動を行える\n失敗のどこを直したのかを言えると、国連の仕組みが理解できる。\n\n【主な機関】総会（全加盟国が1国1票）、安全保障理事会、経済社会理事会、国際司法裁判所、事務局。\n\n【専門機関】国連教育科学文化機関（教育・文化・世界遺産）、世界保健機関（保健）、国連児童基金（子ども）、国連難民高等弁務官事務所（難民）など。\n\n【日本の関わり】分担金を多く負担し、平和維持活動にも参加してきた。非常任理事国に選ばれた回数は最も多い国の一つである。',
