    question: '国際連合で、世界の平和と安全に主要な責任をもち、五つの常任理事国が拒否権をもつ機関を何といいますか。',
    answer: '安全保障理事会',
    hint: '常任理事国は拒否権をもちます。',
    explanation:
      '【答え】安全保障理事会\n\n【構成】常任理事国5か国（アメリカ・イギリス・フランス・ロシア・中国）と、総会が選ぶ非常任理事国10か国（任期2年）の計15か国からなる。\n\n【なぜこの5か国なのか】第二次世界大戦で勝った主な国だからである。国際連合は、その戦争の反省のうえに戦勝国が中心となってつくった組織である。\n\n【拒否権】重要な問題を決めるには、常任理事国5か国すべての賛成が必要である。1か国でも反対すれば、ほかのすべてが賛成しても決議は成立しない。\n\n【なぜ拒否権があるのか】大国が反対したまま決議を押し通しても実行できず、それどころか国連そのものが割れてしまう。大国を組織の中にとどめておくための仕組みである。国際連盟がアメリカの不参加などで力を持てなかった反省もある。\n\n【問題点】当事国が常任理事国だと、決議ができずに機能しなくなる。冷戦の時代には米ソが拒否権を使い合い、安全保障理事会はしばしば動けなかった。安全保障理事会の改革を求める声は長く続いている。\n\n【総会とのちがい】総会は全加盟国が1国1票で、大国も小国も同じ重さである。安全保障理事会だけが例外的な仕組みになっている。',
