    answer: '累進課税（制度）',
    hint: '収入が多いほど税の割合が高くなります。',
    explanation:
      '【答え】累進課税（制度）\n\n【どういう仕組みか】所得が多い人ほど高い税率で税を負担する。日本の所得税では、所得の額に応じて5%から45%まで段階的に税率が上がる。相続税にも使われている。\n\n【なぜこうするのか】所得の多い人と少ない人の差を小さくするためである。集めた税は、社会保障などを通じて所得の少ない人にも回る。これを所得の再分配といい、税の大事な役割の一つである。\n\n【対になる仕組み】消費税はだれが買っても同じ税率である。一見公平に見えるが、所得の少ない人ほど収入に対する負担の割合が重くなる。これを逆進性という。食料品などの税率を低くする軽減税率は、これをやわらげるための工夫である。\n\n【税の分類】\n・直接税 … 負担する人と納める人が同じ。所得税・法人税・相続税\n・間接税 … 負担する人と納める人がちがう。消費税・酒税・関税\n・国税 … 国に納める。地方税 … 都道府県・市町村に納める\n\n【税の3つの役割】①国の活動の費用をまかなう ②所得の差を小さくする ③景気を調整する（好景気には税収が増えて過熱をおさえる）。',
