      '【答え】伊藤博文\n\n【どんな人物か】長州藩（山口県）の出身で、幕末に松下村塾で学んだ。若いころイギリスへひそかに留学し、西洋の力を実際に見たことが、のちの考え方の土台になった。\n\n【憲法づくり】憲法を定めるにあたり、自らヨーロッパへ渡ってドイツ（プロイセン）の憲法を学んだ。君主の権限が強いプロイセンの憲法が、天皇を中心とする日本の仕組みに合うと考えたからである。帰国後、草案づくりを進め、1889年の大日本帝国憲法の発布に結びつけた。\n\n【内閣制度】1890年に国会を開くと約束した以上、それまでに近代的な政治の仕組みを整える必要があった。そこで太政官制をやめ、各大臣が分野ごとに責任を持つ内閣制度に改め、1885年に自ら初代内閣総理大臣となった。憲法・内閣・議会を、順番を決めて整えていったところに、この人の仕事の性格が表れている。\n\n【その後】4度にわたって内閣総理大臣を務め、初代の韓国統監にもなった。1909年、ハルビンで安重根に暗殺された。\n\n【同じ時期の人物】大隈重信（立憲改進党・早稲田大学）、板垣退助（自由党）、陸奥宗光（領事裁判権の撤廃）、小村寿太郎（関税自主権の回復）。',
