      '【答え】御恩と奉公\n\n【どんな関係か】\n・御恩 … 将軍が御家人の先祖からの領地を保護し（本領安堵）、手がらがあれば新しい領地を与える（新恩給与）\n・奉公 … 御家人は、戦いのときに命がけで戦い、ふだんは京都や鎌倉の警備を務める\n土地を仲立ちにした主従関係が、武家政治の土台である。\n\n【なぜ土地なのか】当時、武士にとって土地は生活のすべてだった。土地を保障してもらえるからこそ、命をかけて戦う価値があった。給料としてお金を払う関係ではなく、土地を通じた結びつきだったところが、この時代の特徴である。\n\n【この関係が崩れたとき】元寇（1274年・1281年）は外国からの防衛戦だったので、勝っても新しい土地が手に入らなかった。戦費を自分で負担した御家人に与える恩賞がなく、不満が広がった。御恩がなければ奉公も続かない。幕府と御家人の信頼関係がくずれ、1333年に鎌倉幕府はほろびる。\n\n【あわせて覚える】鎌倉幕府の仕組みは、中央に侍所・政所・問注所、地方に守護（国ごと・軍事と警察）と地頭（荘園ごと・年貢の取り立て）。',
    examFrequency: 'high',
