    explanation:
      '【答え】足利義満\n\n【何をしたのか】\n・1392年、南北朝を統一した。60年近く続いた2つの朝廷の対立を終わらせ、幕府の力を確かなものにした\n・京都の北山に金閣を建てた。公家の文化と武家の文化、そして禅宗の様式が混ざった建物で、この時代の文化（北山文化）を象徴する\n・明との貿易（日明貿易・勘合貿易）を始めた\n\n【なぜ勘合という札を使ったのか】当時、倭寇と呼ばれる海賊が中国沿岸を荒らしていた。明は倭寇を厳しく取りしまるとともに、正式な貿易船と倭寇を見分ける必要があった。そこで、合い札（勘合）を持つ船だけを正式な船として認めた。にせ物を防ぐための身分証明書だったのである。\n\n【なぜ利益が大きかったのか】義満は明の皇帝から「日本国王」と認められる形をとった。これは朝貢貿易であり、貢ぎ物に対して明から手厚い返礼があったため、日本側の利益は非常に大きかった。いっぽう、中国にへりくだる形を取ったことは、後に批判もされた。\n\n【対にして覚える】北山文化＝金閣（足利義満）、東山文化＝銀閣（足利義政・書院造・水墨画）。',
