      '【答え】五箇条の御誓文\n\n【いつ・どんな形で】1868年3月、明治天皇が神に誓うという形で示された、新政府の基本方針である。\n\n【なぜ天皇が神に誓う形にしたのか】新政府はできたばかりで、まだ力も信用もなかった。天皇が神に誓うという重々しい形にすることで方針の重みを示し、諸大名や民衆に新政府を認めさせようとした。形式そのものに意味がある。\n\n【主な内容】\n・広く会議を開き、政治は人々の意見を聞いて決める\n・身分の上下にかかわらず、心を一つにして国を治める\n・これまでのよくない習わしを改める\n・知識を世界に求め、国をさかんにする\n開国して世界から学ぶ姿勢をはっきり示した点が重要である。\n\n【五榜の掲示】同じころ、民衆に向けては五榜の掲示が出され、キリスト教の禁止や一揆の禁止など、江戸時代とあまり変わらない内容が示された。国の方針としては新しいことを言いながら、民衆への統制は古いままだったというずれも知っておきたい。\n\n【その後の流れ】版籍奉還（1869）→ 廃藩置県（1871）→ 学制・徴兵令・地租改正（1872〜73）と、改革が一気に進む。\n\n【よくあるまちがい】御誓文は憲法ではない。憲法（大日本帝国憲法）は1889年である。',
