    hint: '蘭学の発展のきっかけになりました。',
    explanation:
      '【答え】解体新書\n\n【だれが・いつ】1774年、杉田玄白・前野良沢・中川淳庵らが、オランダ語の解剖書『ターヘル・アナトミア』を訳して出版した。\n\n【なぜ訳そうと思ったのか】玄白らは、刑死した人の解剖に立ち会い、その内臓のようすがオランダの本の図とそっくりであることに驚いた。当時の日本の医学書の図とはまるでちがっていた。実際に自分の目で確かめた事実が、どちらの本が正しいかを教えた。ここから「西洋の学問を正しく知らなければならない」と考えて翻訳を決意した。\n\n【どれほど大変だったか】オランダ語の辞書もほとんどない時代で、一つの単語の意味を何日もかけて考えた。神経・軟骨・動脈といった言葉は、このとき新しく作られた訳語で、いまも使われている。玄白はのちに、その苦労を『蘭学事始』に書き残した。\n\n【その後への影響】これをきっかけに蘭学が広まり、緒方洪庵の適塾やシーボルトの鳴滝塾で多くの人が学んだ。福沢諭吉も適塾の出身である。西洋の学問を学ぶ下地が、幕末から明治の近代化を支えた。\n\n【同じころの学問】本居宣長の国学（『古事記伝』）、伊能忠敬の測量。',
