      '【答え】熱帯のうちのサバナ気候\n\n【正しくは「雨が少ない」ではなく「雨季と乾季がある」】サバナ気候は、赤道からやや離れた熱帯に分布する。一年を通して気温は高いが、雨がたくさん降る雨季と、ほとんど降らない乾季がはっきり分かれているのが特徴である。年間の降水量そのものは、けっして少なくない。\n\n【なぜ雨季と乾季ができるのか】赤道付近で空気が上昇して雨を降らせる帯（熱帯収束帯）は、太陽の位置に合わせて南北に移動する。その帯が近づいている時期が雨季、遠ざかっている時期が乾季になる。雨の帯が移動するから、季節が生まれる。\n\n【どんな景色か】丈の高い草原に、まばらに木が生えている。乾季に耐えるため、バオバブのように水をたくわえる木や、根を深くのばす木が育つ。ライオン・シマウマ・キリンなどの大型動物が暮らす。\n\n【熱帯のもう一つの区分】熱帯雨林気候は赤道直下で、一年中雨が多く、背の高い木が何層にも重なる密林になる。\n\n【気候帯の並び】赤道から順に、熱帯雨林 → サバナ → 乾燥帯（ステップ → 砂漠）→ 温帯 → 冷帯 → 寒帯。赤道から離れるほど雨が減っていくという流れで覚える。',
